INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(951, 98, '_elementor_page_settings', 'a:45:{s:13:\"system_colors\";a:4:{i:0;a:3:{s:3:\"_id\";s:7:\"primary\";s:5:\"title\";s:9:\"Principal\";s:5:\"color\";s:7:\"#6B0F3A\";}i:1;a:3:{s:3:\"_id\";s:9:\"secondary\";s:5:\"title\";s:10:\"Secundario\";s:5:\"color\";s:7:\"#241016\";}i:2;a:3:{s:3:\"_id\";s:4:\"text\";s:5:\"title\";s:5:\"Texto\";s:5:\"color\";s:7:\"#241016\";}i:3;a:3:{s:3:\"_id\";s:6:\"accent\";s:5:\"title\";s:8:\"Énfasis\";s:5:\"color\";s:7:\"#B8935A\";}}s:13:\"custom_colors\";a:2:{i:0;a:3:{s:3:\"_id\";s:7:\"6ea55e0\";s:5:\"title\";s:5:\"Crema\";s:5:\"color\";s:7:\"#F7F1EA\";}i:1;a:3:{s:3:\"_id\";s:7:\"3b65817\";s:5:\"title\";s:6:\"Piedra\";s:5:\"color\";s:7:\"#E4DBD2\";}}s:17:\"system_typography\";a:4:{i:0;a:5:{s:3:\"_id\";s:7:\"primary\";s:5:\"title\";s:9:\"Principal\";s:21:\"typography_typography\";s:6:\"custom\";s:22:\"typography_font_family\";s:16:\"Playfair Display\";s:22:\"typography_font_weight\";s:3:\"500\";}i:1;a:5:{s:3:\"_id\";s:9:\"secondary\";s:5:\"title\";s:10:\"Secundario\";s:21:\"typography_typography\";s:6:\"custom\";s:22:\"typography_font_family\";s:4:\"Lato\";s:22:\"typography_font_weight\";s:3:\"500\";}i:2;a:5:{s:3:\"_id\";s:4:\"text\";s:5:\"title\";s:5:\"Texto\";s:21:\"typography_typography\";s:6:\"custom\";s:22:\"typography_font_family\";s:4:\"Lato\";s:22:\"typography_font_weight\";s:3:\"400\";}i:3;a:5:{s:3:\"_id\";s:6:\"accent\";s:5:\"title\";s:8:\"Énfasis\";s:21:\"typography_typography\";s:6:\"custom\";s:22:\"typography_font_family\";s:4:\"Lato\";s:22:\"typography_font_weight\";s:3:\"700\";}}s:17:\"custom_typography\";a:0:{}s:21:\"default_generic_fonts\";s:10:\"Sans-serif\";s:9:\"site_name\";s:6:\"CHICHA\";s:19:\"page_title_selector\";s:14:\"h1.entry-title\";s:10:\"custom_css\";s:15629:\"/* ---------- 1. Variables globales y base ---------- */\r\n:root {\r\n  --ch-vino: #6B0F3A;\r\n  --ch-vino-osc: #4D0A2A;\r\n  --ch-carbon: #241016;\r\n  --ch-crema: #F7F1EA;\r\n  --ch-piedra: #E4DBD2;\r\n  --ch-oro: #B8935A;\r\n  --ch-ok: #5C7A4C;\r\n  --ch-no: #A4524A;\r\n  --ch-linea: #E6DDD3;\r\n  --ch-serif: \'Playfair Display\', Georgia, serif;\r\n  --ch-sans: \'Lato\', system-ui, sans-serif;\r\n}\r\n\r\nhtml {\r\n  scroll-behavior: smooth;\r\n}\r\n\r\nbody {\r\n  background-color: #140A0E !important; /* Fondo exterior oscuro general */\r\n  color: var(--ch-carbon);\r\n  font-family: var(--ch-sans);\r\n  margin: 0;\r\n  padding: 24px 0;\r\n}\r\n\r\n::selection {\r\n  background: var(--ch-vino);\r\n  color: #fff;\r\n}\r\n\r\n/* ---------- 1B. Estilo en caja flotante (Boxed Layout 960px) ---------- */\r\n#page, \r\n.site-main, \r\n.elementor-location-header, \r\nheader.site-header, \r\n.elementor-location-footer, \r\nfooter.site-footer {\r\n  max-width: 960px !important;\r\n  margin-left: auto !important;\r\n  margin-right: auto !important;\r\n}\r\n\r\n/* Envoltorio principal con esquinas redondeadas y sombra */\r\n#page {\r\n  background-color: var(--ch-crema);\r\n  border-radius: 16px;\r\n  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);\r\n  border: 1px solid rgba(255, 255, 255, 0.08);\r\n  overflow: hidden;\r\n}\r\n\r\n/* Esquinas redondeadas superiores e inferiores si Header/Footer están independizados en Elementor Theme Builder */\r\n.elementor-location-header, \r\nheader.site-header {\r\n  border-radius: 16px 16px 0 0 !important;\r\n  overflow: hidden;\r\n}\r\n\r\n.elementor-location-footer, \r\nfooter.site-footer {\r\n  border-radius: 0 0 16px 16px !important;\r\n  overflow: hidden;\r\n}\r\n\r\n@media (max-width: 980px) {\r\n  body {\r\n    padding: 0;\r\n  }\r\n  #page, \r\n  .site-main, \r\n  .elementor-location-header, \r\n  header.site-header, \r\n  .elementor-location-footer, \r\n  footer.site-footer {\r\n    max-width: 100% !important;\r\n    border-radius: 0 !important;\r\n    border: none !important;\r\n    box-shadow: none !important;\r\n  }\r\n}\r\n\r\n/* ---------- 2. Header & Menú de Navegación ---------- */\r\n.ch-header {\r\n  background: var(--ch-crema);\r\n  border-bottom: 1px solid var(--ch-linea);\r\n}\r\n\r\n.ch-header.elementor-sticky--effects {\r\n  box-shadow: 0 1px 0 var(--ch-linea);\r\n}\r\n\r\n/* Variante transparente solo para Inicio: ch-header ch-transparente */\r\n.ch-header.ch-transparente {\r\n  position: absolute;\r\n  left: 0;\r\n  right: 0;\r\n  z-index: 10;\r\n  background: transparent;\r\n  border-bottom: 1px solid rgba(255, 255, 255, .25);\r\n}\r\n\r\n.ch-header.ch-transparente.elementor-sticky--effects {\r\n  background: rgba(247, 241, 234, .97);\r\n  border-bottom-color: var(--ch-linea);\r\n}\r\n\r\n/* Menú (clase ch-nav en el widget Menú; Puntero: Ninguno) */\r\n.ch-nav .elementor-item {\r\n  font-family: var(--ch-sans);\r\n  font-size: 12px;\r\n  letter-spacing: .16em;\r\n  text-transform: uppercase;\r\n  color: var(--ch-carbon);\r\n  transition: color 0.3s ease;\r\n}\r\n\r\n.ch-nav .elementor-item:hover,\r\n.ch-nav .elementor-item.elementor-item-active {\r\n  color: var(--ch-vino);\r\n}\r\n\r\n.ch-nav .elementor-item.elementor-item-active {\r\n  border-bottom: 1px solid var(--ch-vino);\r\n}\r\n\r\n.ch-header.ch-transparente .ch-nav .elementor-item {\r\n  color: #fff;\r\n}\r\n\r\n.ch-header.ch-transparente.elementor-sticky--effects .ch-nav .elementor-item {\r\n  color: var(--ch-carbon);\r\n}\r\n\r\n/* Animación suave para menú desplegable (móvil) */\r\n.ch-nav .elementor-nav-menu--dropdown {\r\n  transition: max-height 0.4s ease-in-out, opacity 0.3s ease-in-out, transform 0.3s ease-in-out !important;\r\n  overflow: hidden;\r\n}\r\n\r\n.ch-nav .elementor-nav-menu--dropdown a {\r\n  transition: background-color 0.2s ease, color 0.2s ease !important;\r\n}\r\n\r\n/* ---------- 3. Portada, banners y franja con foto ---------- */\r\n.ch-portada, .ch-banner, .ch-franja {\r\n  position: relative;\r\n  overflow: hidden;\r\n  color: #fff;\r\n  text-align: center;\r\n  background-color: #3B2B2F;\r\n  background-size: cover;\r\n  background-position: center;\r\n}\r\n\r\n.ch-portada::before, .ch-banner::before, .ch-franja::before {\r\n  content: \"\";\r\n  position: absolute;\r\n  inset: 0;\r\n  z-index: 1;\r\n  pointer-events: none;\r\n  background: linear-gradient(rgba(36, 16, 22, .62), rgba(36, 16, 22, .8));\r\n}\r\n\r\n.ch-portada > .e-con-inner, .ch-banner > .e-con-inner, .ch-franja > .e-con-inner,\r\n.ch-portada > .elementor-element, .ch-banner > .elementor-element, .ch-franja > .elementor-element {\r\n  position: relative;\r\n  z-index: 2;\r\n}\r\n\r\n.ch-portada {\r\n  min-height: 90vh;\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: center;\r\n  align-items: center;\r\n}\r\n\r\n.ch-banner {\r\n  min-height: 240px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: center;\r\n  align-items: center;\r\n}\r\n\r\n.ch-franja {\r\n  min-height: 300px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: center;\r\n  align-items: center;\r\n  background-attachment: fixed;\r\n}\r\n\r\n@media (max-width: 1024px) {\r\n  .ch-franja {\r\n    background-attachment: scroll;\r\n  }\r\n}\r\n\r\n/* ---------- 4. Textos ---------- */\r\n.elementor-element.ch-titulo-xl .elementor-heading-title {\r\n  font-family: var(--ch-serif);\r\n  font-weight: 500;\r\n  font-size: clamp(40px, 9vw, 68px);\r\n  letter-spacing: .1em;\r\n  line-height: 1;\r\n  color: #fff;\r\n}\r\n\r\n.elementor-element.ch-subtitulo .elementor-heading-title {\r\n  font-family: var(--ch-sans);\r\n  font-weight: 400;\r\n  font-size: 12px;\r\n  letter-spacing: .45em;\r\n  text-transform: uppercase;\r\n  color: #E9D8B8;\r\n}\r\n\r\n.elementor-element.ch-titulo .elementor-heading-title {\r\n  font-family: var(--ch-serif);\r\n  font-weight: 500;\r\n  font-size: clamp(26px, 4vw, 32px);\r\n  letter-spacing: .04em;\r\n  color: var(--ch-carbon);\r\n  text-align: center;\r\n}\r\n\r\n.ch-titulo .elementor-heading-title::after {\r\n  content: \"\";\r\n  display: block;\r\n  width: 36px;\r\n  height: 1px;\r\n  background: var(--ch-oro);\r\n  margin: 12px auto 0;\r\n}\r\n\r\n.elementor-element.ch-titulo-claro .elementor-heading-title {\r\n  font-family: var(--ch-serif);\r\n  font-weight: 500;\r\n  font-size: clamp(28px, 5vw, 38px);\r\n  letter-spacing: .04em;\r\n  color: #fff;\r\n  text-align: center;\r\n}\r\n\r\n.elementor-element.ch-etiqueta .elementor-heading-title {\r\n  font-family: var(--ch-serif);\r\n  font-style: italic;\r\n  font-weight: 500;\r\n  font-size: 20px;\r\n  color: var(--ch-oro);\r\n  text-align: center;\r\n}\r\n\r\n.elementor-element.ch-frase .elementor-heading-title {\r\n  font-family: var(--ch-serif);\r\n  font-style: italic;\r\n  font-weight: 500;\r\n  font-size: clamp(22px, 4vw, 30px);\r\n  color: #fff;\r\n  text-align: center;\r\n}\r\n\r\n.ch-horario {\r\n  display: inline-block;\r\n  border: 1px solid rgba(255, 255, 255, .55);\r\n  padding: 6px 14px;\r\n  font-size: 12px;\r\n  letter-spacing: .12em;\r\n  color: #fff;\r\n}\r\n\r\n/* ---------- 5. Botones ---------- */\r\n.elementor-button {\r\n  font-family: var(--ch-sans);\r\n  font-weight: 700;\r\n  font-size: 12px;\r\n  letter-spacing: .16em;\r\n  text-transform: uppercase;\r\n  border-radius: 0;\r\n  transition: background .3s, color .3s, border-color .3s;\r\n}\r\n\r\n.elementor-element.ch-btn .elementor-button {\r\n  background: var(--ch-vino);\r\n  color: #fff;\r\n  border: 1px solid var(--ch-vino);\r\n}\r\n\r\n.ch-btn .elementor-button:hover {\r\n  background: var(--ch-vino-osc);\r\n  border-color: var(--ch-vino-osc);\r\n  color: #fff;\r\n}\r\n\r\n.elementor-element.ch-btn-borde .elementor-button {\r\n  background: transparent;\r\n  color: var(--ch-vino);\r\n  border: 1px solid var(--ch-vino);\r\n}\r\n\r\n.ch-btn-borde .elementor-button:hover {\r\n  background: var(--ch-vino);\r\n  color: #fff;\r\n}\r\n\r\n.elementor-element.ch-btn-claro .elementor-button {\r\n  background: transparent;\r\n  color: #fff;\r\n  border: 1px solid #fff;\r\n}\r\n\r\n.ch-btn-claro .elementor-button:hover {\r\n  background: #fff;\r\n  color: var(--ch-vino);\r\n}\r\n\r\n/* ---------- 6. Tarjetas, fotos y galería ---------- */\r\n.ch-tarjeta {\r\n  background: #fff;\r\n  border: 1px solid var(--ch-linea);\r\n  padding: 14px;\r\n  text-align: center;\r\n  transition: border-color .3s;\r\n}\r\n\r\n.ch-tarjeta:hover {\r\n  border-color: var(--ch-vino);\r\n}\r\n\r\n.ch-tarjeta .elementor-image-box-title {\r\n  font-family: var(--ch-serif);\r\n  font-weight: 500;\r\n  color: var(--ch-vino);\r\n  font-size: 20px;\r\n}\r\n\r\n.ch-tarjeta img {\r\n  width: 100%;\r\n  aspect-ratio: 4/3;\r\n  object-fit: cover;\r\n}\r\n\r\n.ch-zoom {\r\n  overflow: hidden;\r\n}\r\n\r\n.ch-zoom img {\r\n  transition: transform .6s ease;\r\n}\r\n\r\n.ch-zoom:hover img, .ch-tarjeta:hover .ch-zoom img {\r\n  transform: scale(1.05);\r\n}\r\n\r\n.ch-galeria img {\r\n  width: 100%;\r\n  aspect-ratio: 3/4;\r\n  object-fit: cover;\r\n}\r\n\r\n.ch-galeria .elementor-gallery-item__image {\r\n  aspect-ratio: 3/4;\r\n}\r\n\r\n.ch-acordeon .elementor-tab-title {\r\n  font-family: var(--ch-serif);\r\n  font-size: 20px;\r\n  color: var(--ch-vino);\r\n  border-bottom: 1px solid var(--ch-linea);\r\n}\r\n\r\n.ch-acordeon .elementor-tab-content {\r\n  border-color: var(--ch-linea);\r\n  color: var(--ch-carbon);\r\n}\r\n\r\n/* ---------- 7. Formularios (clase ch-form en el widget Formulario) ---------- */\r\n.ch-form .elementor-field-label {\r\n  font-family: var(--ch-sans);\r\n  font-weight: 700;\r\n  font-size: 12px;\r\n  letter-spacing: .1em;\r\n  text-transform: uppercase;\r\n  color: #6B5A5F;\r\n}\r\n\r\n.ch-form .elementor-field-textual {\r\n  border: 1px solid #CFC4BA;\r\n  border-radius: 0;\r\n  background: #fff;\r\n  color: var(--ch-carbon);\r\n  padding: 10px;\r\n}\r\n\r\n.ch-form .elementor-field-textual:focus {\r\n  border-color: var(--ch-vino);\r\n  outline: none;\r\n  box-shadow: none;\r\n}\r\n\r\n.ch-form .elementor-button {\r\n  background: var(--ch-vino);\r\n  color: #fff;\r\n  border-radius: 0;\r\n}\r\n\r\n.ch-form .elementor-message-success {\r\n  color: var(--ch-ok);\r\n}\r\n\r\n.ch-form .elementor-message-danger {\r\n  color: var(--ch-no);\r\n}\r\n\r\n/* ---------- 8. Popups (ventanas de los platos) ---------- */\r\n.dialog-widget.dialog-lightbox-widget {\r\n  background: rgba(36, 16, 22, .78);\r\n}\r\n\r\n.elementor-popup-modal .dialog-widget-content {\r\n  border-radius: 0;\r\n  box-shadow: 0 20px 60px rgba(0, 0, 0, .35);\r\n}\r\n\r\n.elementor-popup-modal .dialog-close-button {\r\n  color: var(--ch-vino);\r\n}\r\n\r\n.ch-popup img {\r\n  width: 100%;\r\n  aspect-ratio: 4/3;\r\n  object-fit: cover;\r\n}\r\n\r\n.elementor-element.ch-precio .elementor-heading-title {\r\n  font-family: var(--ch-serif);\r\n  font-weight: 500;\r\n  font-size: 26px;\r\n  color: var(--ch-vino);\r\n}\r\n\r\n/* ---------- 9. Pie de página (clase ch-pie en el contenedor) ---------- */\r\n.ch-pie {\r\n  background: var(--ch-carbon);\r\n  color: #E8DCD4;\r\n  font-size: 13px;\r\n}\r\n\r\n.ch-pie .elementor-heading-title {\r\n  font-family: var(--ch-serif);\r\n  font-weight: 500;\r\n  font-size: 18px;\r\n  color: #E9D8B8;\r\n}\r\n\r\n.ch-pie a {\r\n  color: #E8DCD4;\r\n}\r\n\r\n.ch-pie a:hover {\r\n  color: #fff;\r\n}\r\n\r\n.ch-pie .ch-form .elementor-button {\r\n  background: #fff;\r\n  color: var(--ch-vino);\r\n}\r\n\r\n.ch-pie-base {\r\n  border-top: 1px solid rgba(255, 255, 255, .14);\r\n  font-size: 11px;\r\n  letter-spacing: .05em;\r\n  opacity: .85;\r\n  text-align: center;\r\n}\r\n\r\n/* ---------- 10. Aplicación de reserva (widgets HTML) ---------- */\r\n.ch-app {\r\n  max-width: 520px;\r\n  margin: 0 auto;\r\n  font-family: var(--ch-sans);\r\n  font-size: 15px;\r\n  line-height: 1.6;\r\n  color: var(--ch-carbon);\r\n}\r\n\r\n.ch-app h2, .ch-app h3 {\r\n  font-family: var(--ch-serif);\r\n  font-weight: 500;\r\n  color: var(--ch-vino);\r\n  margin: 0 0 6px;\r\n}\r\n\r\n.ch-app h3 {\r\n  font-size: 20px;\r\n}\r\n\r\n.ch-app .c {\r\n  background: #fff;\r\n  border: 1px solid var(--ch-linea);\r\n  padding: 14px;\r\n  text-align: center;\r\n}\r\n\r\n.ch-app .c.l {\r\n  text-align: left;\r\n}\r\n\r\n.ch-app .b {\r\n  font: 700 12px var(--ch-sans);\r\n  letter-spacing: .16em;\r\n  text-transform: uppercase;\r\n  background: transparent;\r\n  color: var(--ch-vino);\r\n  border: 1px solid var(--ch-vino);\r\n  padding: 12px 22px;\r\n  cursor: pointer;\r\n  border-radius: 0;\r\n  transition: background .3s, color .3s;\r\n}\r\n\r\n.ch-app .b.m {\r\n  background: var(--ch-vino);\r\n  color: #fff;\r\n}\r\n\r\n.ch-app .b:hover {\r\n  background: var(--ch-vino-osc);\r\n  border-color: var(--ch-vino-osc);\r\n  color: #fff;\r\n}\r\n\r\n.ch-app .bt {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 10px;\r\n  margin: 12px 0;\r\n}\r\n\r\n.ch-app .steps {\r\n  display: flex;\r\n  gap: 4px;\r\n  flex-wrap: wrap;\r\n  margin-bottom: 18px;\r\n  font-size: 11px;\r\n  letter-spacing: .05em;\r\n}\r\n\r\n.ch-app .steps span {\r\n  flex: 1;\r\n  min-width: 64px;\r\n  text-align: center;\r\n  padding: 6px 2px;\r\n  border: 1px solid #D9CFC6;\r\n  color: #8A7D73;\r\n}\r\n\r\n.ch-app .steps .a {\r\n  background: var(--ch-vino);\r\n  border-color: var(--ch-vino);\r\n  color: #fff;\r\n}\r\n\r\n.ch-app .cal {\r\n  display: grid;\r\n  grid-template-columns: repeat(7, 1fr);\r\n  gap: 4px;\r\n  text-align: center;\r\n}\r\n\r\n.ch-app .cal button, .ch-app .cal span {\r\n  padding: 9px 0;\r\n  border: 0;\r\n  border-radius: 0;\r\n  background: var(--ch-ok);\r\n  color: #fff;\r\n  font: inherit;\r\n  font-size: 13px;\r\n}\r\n\r\n.ch-app .cal button {\r\n  cursor: pointer;\r\n}\r\n\r\n.ch-app .cal .l {\r\n  background: var(--ch-no);\r\n}\r\n\r\n.ch-app .cal .x {\r\n  background: var(--ch-piedra);\r\n  color: #A39588;\r\n}\r\n\r\n.ch-app .cal .s {\r\n  background: var(--ch-vino);\r\n}\r\n\r\n.ch-app .cal .h {\r\n  background: none;\r\n  color: #8A7D73;\r\n  font-weight: 700;\r\n}\r\n\r\n.ch-app .cal .e {\r\n  background: none;\r\n}\r\n\r\n.ch-app .hrs {\r\n  display: flex;\r\n  gap: 6px;\r\n  flex-wrap: wrap;\r\n  margin: 10px 0;\r\n}\r\n\r\n.ch-app .hrs button {\r\n  border: 1px solid var(--ch-vino);\r\n  background: #fff;\r\n  color: var(--ch-vino);\r\n  padding: 6px 12px;\r\n  font: inherit;\r\n  cursor: pointer;\r\n  border-radius: 0;\r\n}\r\n\r\n.ch-app .hrs .s {\r\n  background: var(--ch-vino);\r\n  color: #fff;\r\n}\r\n\r\n.ch-app .pl {\r\n  background: #fff;\r\n  border: 1px solid var(--ch-linea);\r\n  padding: 8px;\r\n  margin-bottom: 8px;\r\n}\r\n\r\n.ch-app .pl small {\r\n  display: block;\r\n  margin-bottom: 6px;\r\n  font-size: 11px;\r\n  letter-spacing: .12em;\r\n  color: #6B5A5F;\r\n}\r\n\r\n.ch-app .mz {\r\n  display: grid;\r\n  grid-template-columns: repeat(4, 1fr);\r\n  gap: 6px;\r\n}\r\n\r\n.ch-app .mz button {\r\n  border: 0;\r\n  border-radius: 0;\r\n  padding: 12px 0;\r\n  background: var(--ch-ok);\r\n  color: #fff;\r\n  font: 700 13px var(--ch-sans);\r\n  cursor: pointer;\r\n}\r\n\r\n.ch-app .mz .r {\r\n  background: var(--ch-no);\r\n  cursor: not-allowed;\r\n}\r\n\r\n.ch-app .mz .s {\r\n  background: var(--ch-vino);\r\n}\r\n\r\n.ch-app input, .ch-app select, .ch-app textarea {\r\n  width: 100%;\r\n  font: inherit;\r\n  padding: 10px;\r\n  margin: 4px 0 10px;\r\n  border: 1px solid #CFC4BA;\r\n  border-radius: 0;\r\n  background: #fff;\r\n  color: var(--ch-carbon);\r\n}\r\n\r\n.ch-app input:focus, .ch-app select:focus {\r\n  border-color: var(--ch-vino);\r\n  outline: none;\r\n}\r\n\r\n.ch-app label {\r\n  font-size: 12px;\r\n  letter-spacing: .1em;\r\n  text-transform: uppercase;\r\n  color: #6B5A5F;\r\n}\r\n\r\n.ch-app .er {\r\n  min-height: 18px;\r\n  font-size: 13px;\r\n  color: var(--ch-no);\r\n}\r\n\r\n.ch-app .ln {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  gap: 8px;\r\n  padding: 6px 0;\r\n  border-bottom: 1px solid var(--ch-linea);\r\n}\r\n\r\n.ch-app .nt {\r\n  margin: 8px 0;\r\n  font-size: 12px;\r\n  opacity: .7;\r\n}\r\n\r\n.ch-app .st {\r\n  display: inline-block;\r\n  padding: 2px 20px;\r\n  border: 3px double;\r\n  font: 600 28px var(--ch-serif);\r\n  letter-spacing: .2em;\r\n  transform: rotate(-3deg);\r\n}\r\n\r\n.ch-app .st.p {\r\n  color: var(--ch-ok);\r\n}\r\n\r\n.ch-app .st.d {\r\n  color: var(--ch-no);\r\n}\r\n\r\n.ch-app .bar {\r\n  position: sticky;\r\n  bottom: 0;\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  gap: 8px;\r\n  flex-wrap: wrap;\r\n  padding: 10px 16px;\r\n  background: var(--ch-carbon);\r\n  color: #fff;\r\n}\r\n\r\n/* ---------- 11. Impresión ---------- */\r\n@media print {\r\n  .elementor-location-header, .elementor-location-footer, .ch-sinimprimir, .ch-app .bt {\r\n    display: none !important;\r\n  }\r\n  body {\r\n    background: #fff !important;\r\n  }\r\n}\r\n\r\n/* ---------- 12. Accesibilidad ---------- */\r\n@media (prefers-reduced-motion: reduce) {\r\n  * {\r\n    animation: none !important;\r\n    transition: none !important;\r\n    scroll-behavior: auto !important;\r\n  }\r\n}\";s:27:\"hello_footer_copyright_text\";s:29:\"Todos los derechos reservados\";s:11:\"viewport_md\";i:768;s:11:\"viewport_lg\";i:1025;s:16:\"site_description\";s:14:\"Cocina peruana\";s:32:\"colors_enable_styleguide_preview\";s:3:\"yes\";s:15:\"activeItemIndex\";i:1;s:36:\"typography_enable_styleguide_preview\";s:3:\"yes\";s:26:\"body_typography_typography\";s:6:\"custom\";s:27:\"body_typography_font_family\";s:4:\"Lato\";s:33:\"link_normal_typography_typography\";s:6:\"custom\";s:34:\"link_normal_typography_font_family\";s:16:\"Playfair Display\";s:34:\"link_normal_typography_font_weight\";s:3:\"500\";s:24:\"h1_typography_typography\";s:6:\"custom\";s:25:\"h1_typography_font_family\";s:16:\"Playfair Display\";s:25:\"h1_typography_font_weight\";s:3:\"500\";s:24:\"h2_typography_typography\";s:6:\"custom\";s:25:\"h2_typography_font_family\";s:16:\"Playfair Display\";s:25:\"h2_typography_font_weight\";s:3:\"500\";s:24:\"h3_typography_typography\";s:6:\"custom\";s:25:\"h3_typography_font_family\";s:16:\"Playfair Display\";s:25:\"h3_typography_font_weight\";s:3:\"500\";s:24:\"h4_typography_typography\";s:6:\"custom\";s:25:\"h4_typography_font_family\";s:16:\"Playfair Display\";s:25:\"h4_typography_font_weight\";s:3:\"500\";s:24:\"h5_typography_typography\";s:6:\"custom\";s:25:\"h5_typography_font_family\";s:16:\"Playfair Display\";s:25:\"h5_typography_font_weight\";s:3:\"500\";s:24:\"h6_typography_typography\";s:6:\"custom\";s:25:\"h6_typography_font_family\";s:16:\"Playfair Display\";s:25:\"h6_typography_font_weight\";s:3:\"500\";s:9:\"site_logo\";a:5:{s:3:\"url\";s:80:\"http://localhost/restaurante/wp-content/uploads/2026/10/logo-chicha-circular.svg\";s:2:\"id\";i:60;s:4:\"size\";s:0:\"\";s:3:\"alt\";s:0:\"\";s:6:\"source\";s:7:\"library\";}s:12:\"site_favicon\";a:5:{s:3:\"url\";s:74:\"http://localhost/restaurante/wp-content/uploads/2026/10/favicon-chicha.svg\";s:2:\"id\";i:61;s:4:\"size\";s:0:\"\";s:3:\"alt\";s:0:\"\";s:6:\"source\";s:7:\"library\";}s:21:\"default_page_template\";s:23:\"elementor_header_footer\";s:44:\"settings_page_transitions_entrance_animation\";s:13:\"fade-out-down\";s:40:\"settings_page_transitions_exit_animation\";s:13:\"fade-in-right\";s:25:\"mobile_browser_background\";s:7:\"#FBF5F1\";s:15:\"container_width\";a:3:{s:4:\"unit\";s:2:\"px\";s:4:\"size\";i:960;s:5:\"sizes\";a:0:{}}}'),
