(1269, 128, '_elementor_data', '[{\"id\":\"03300a5\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"a1b8d8b\",\"elType\":\"widget\",\"settings\":{\"html\":\"<!--\\n  CHICHA \\u00b7 Widget de RESERVA (calendario \\u2192 mesa \\u2192 pedido \\u2192 pago \\u2192 comprobante)\\n  D\\u00f3nde pegarlo: p\\u00e1gina \\\"Reserva\\\" \\u2192 widget HTML de Elementor.\\n  Requiere el CSS global (secci\\u00f3n 10, clase ch-app).\\n-->\\n<style>\\n.ch-app .b[disabled]{opacity:.4;cursor:not-allowed}\\n.ch-app .b[disabled]:hover{background:transparent;color:var(--ch-vino);border-color:var(--ch-vino)}\\n.ch-app .ln.sin{border:0}\\n<\\/style>\\n\\n<div class=\\\"ch-app\\\" id=\\\"chReserva\\\"><\\/div>\\n\\n<script>\\n(function () {\\n  \\/* ===== Ajustes (c\\u00e1mbialos si hace falta) ===== *\\/\\n  \\/\\/ P\\u00e1gina a la que va \\\"Finalizar\\\". En XAMPP con subcarpeta: \'\\/nombre-carpeta\\/gracias\\/\'\\n  var GRACIAS = \'\\/gracias\\/\';\\n  var GARANTIA = 20; \\/\\/ S\\/ si no se elige ning\\u00fan plato\\n  var HORAS = [\'12:00\', \'13:30\', \'15:00\', \'19:00\', \'20:30\'];\\n  var MENU = [\\n    { n: \'Cebiche de trucha\', p: 38 }, { n: \'Alpaca carpaccio\', p: 45 },\\n    { n: \'Cuy confitado\', p: 55 },     { n: \'Rocotos rellenos\', p: 32 },\\n    { n: \'Chicha morada\', p: 8 },      { n: \'Limonada\', p: 7 }, { n: \'Maracuy\\u00e1\', p: 8 }\\n  ];\\n  var KEY_DB = \'chicha_reservas\', KEY_PED = \'chicha_pedido\';\\n  var MESES = [\'Enero\',\'Febrero\',\'Marzo\',\'Abril\',\'Mayo\',\'Junio\',\'Julio\',\'Agosto\',\'Septiembre\',\'Octubre\',\'Noviembre\',\'Diciembre\'];\\n  var DIAS = [\'Dom\',\'Lun\',\'Mar\',\'Mi\\u00e9\',\'Jue\',\'Vie\',\'S\\u00e1b\'];\\n\\n  var root = document.getElementById(\'chReserva\');\\n  if (!root) return;\\n\\n  \\/* ===== Utilidades ===== *\\/\\n  function ld(k, ses) { try { return JSON.parse((ses ? sessionStorage : localStorage).getItem(k)); } catch (e) { return null; } }\\n  function sv(k, v, ses) { try { (ses ? sessionStorage : localStorage).setItem(k, JSON.stringify(v)); } catch (e) {} }\\n  function esc(s) { return String(s).replace(\\/[&<>\\\"\']\\/g, function (c) { return { \'&\': \'&amp;\', \'<\': \'&lt;\', \'>\': \'&gt;\', \'\\\"\': \'&quot;\', \\\"\'\\\": \'&#39;\' }[c]; }); }\\n  function pad(n) { return n < 10 ? \'0\' + n : \'\' + n; }\\n  function iso(y, m, d) { return y + \'-\' + pad(m + 1) + \'-\' + pad(d); }\\n  function tot(a) { return a.reduce(function (x, y) { return x + y.p; }, 0); }\\n  function etiqueta(f) {\\n    var p = f.split(\'-\'), d = new Date(+p[0], +p[1] - 1, +p[2]);\\n    return DIAS[d.getDay()] + \' \' + (+p[2]) + \' \' + MESES[+p[1] - 1].slice(0, 3).toLowerCase();\\n  }\\n\\n  \\/* ===== Estado ===== *\\/\\n  var hoy = new Date();\\n  var HOY = iso(hoy.getFullYear(), hoy.getMonth(), hoy.getDate());\\n  var S = {\\n    paso: 1, y: hoy.getFullYear(), m: hoy.getMonth(),\\n    fecha: null, hora: null, mesa: null, nombre: \'\', pers: 2,\\n    pedido: ld(KEY_PED, true) || [], pago: null, last: null\\n  };\\n\\n  \\/* ===== Disponibilidad simulada ===== *\\/\\n  function lleno(y, m, d) { return (d * 7 + m * 3 + y) % 6 === 0; }\\n  function ocupada(n) {\\n    var k = S.fecha + S.hora, h = 0, i;\\n    for (i = 0; i < k.length; i++) h = (h * 31 + k.charCodeAt(i)) >>> 0;\\n    var reservas = ld(KEY_DB) || [];\\n    var tomada = reservas.some(function (r) { return r.iso === S.fecha && r.h === S.hora && r.m === n; });\\n    return tomada || (h + n * 17) % 5 === 0;\\n  }\\n\\n  \\/* ===== Vistas ===== *\\/\\n  function pasos() {\\n    return \'<div class=\\\"steps\\\">\' + [\'Fecha\', \'Mesa\', \'Pedido\', \'Pago\', \'Comprobante\'].map(function (x, i) {\\n      return \'<span class=\\\"\' + (i + 1 === S.paso ? \'a\' : \'\') + \'\\\">\' + (i + 1) + \'. \' + x + \'<\\/span>\';\\n    }).join(\'\') + \'<\\/div>\';\\n  }\\n\\n  function vFecha() {\\n    var y = S.y, m = S.m;\\n    var dif = (y - hoy.getFullYear()) * 12 + (m - hoy.getMonth());\\n    var h = \'<div class=\\\"ln sin\\\"><button class=\\\"b\\\" data-nav=\\\"-1\\\"\' + (dif <= 0 ? \' disabled\' : \'\') + \'>\\u2039<\\/button>\' +\\n      \'<h3 style=\\\"margin:0;align-self:center\\\">\' + MESES[m] + \' \' + y + \'<\\/h3>\' +\\n      \'<button class=\\\"b\\\" data-nav=\\\"1\\\"\' + (dif >= 2 ? \' disabled\' : \'\') + \'>\\u203a<\\/button><\\/div>\';\\n    h += \'<div class=\\\"cal\\\">\' + \'LMMJVSD\'.split(\'\').map(function (d) { return \'<span class=\\\"h\\\">\' + d + \'<\\/span>\'; }).join(\'\');\\n    var off = (new Date(y, m, 1).getDay() + 6) % 7, n = new Date(y, m + 1, 0).getDate(), d, i;\\n    for (i = 0; i < off; i++) h += \'<span class=\\\"e\\\"><\\/span>\';\\n    for (d = 1; d <= n; d++) {\\n      var f = iso(y, m, d);\\n      if (f < HOY) h += \'<span class=\\\"x\\\">\' + d + \'<\\/span>\';\\n      else if (lleno(y, m, d)) h += \'<span class=\\\"l\\\">\' + d + \'<\\/span>\';\\n      else h += \'<button class=\\\"\' + (f === S.fecha ? \'s\' : \'\') + \'\\\" data-d=\\\"\' + f + \'\\\">\' + d + \'<\\/button>\';\\n    }\\n    h += \'<\\/div><p class=\\\"nt\\\">Verde: libre \\u00b7 Rojo: lleno \\u00b7 Morado: tu elecci\\u00f3n<\\/p>\';\\n    if (S.fecha) {\\n      var ahora = hoy.getHours() * 60 + hoy.getMinutes();\\n      var hs = HORAS.filter(function (x) {\\n        if (S.fecha !== HOY) return true;\\n        var p = x.split(\':\'); return (+p[0]) * 60 + (+p[1]) > ahora;\\n      });\\n      h += \'<h3>Horas libres \\u00b7 \' + etiqueta(S.fecha) + \'<\\/h3>\';\\n      h += hs.length ? \'<div class=\\\"hrs\\\">\' + hs.map(function (x) {\\n        return \'<button class=\\\"\' + (x === S.hora ? \'s\' : \'\') + \'\\\" data-h=\\\"\' + x + \'\\\">\' + x + \'<\\/button>\';\\n      }).join(\'\') + \'<\\/div>\' : \'<p class=\\\"nt\\\">Ya no quedan horas para hoy. Elige otro d\\u00eda.<\\/p>\';\\n    }\\n    return h;\\n  }\\n\\n  function mesaBtn(n) {\\n    var o = ocupada(n);\\n    return \'<button class=\\\"\' + (o ? \'r\' : n === S.mesa ? \'s\' : \'\') + \'\\\" \' + (o ? \'disabled\' : \'data-m=\\\"\' + n + \'\\\"\') + \'>\' + n + \'<\\/button>\';\\n  }\\n  function vMesa() {\\n    var opts = [1, 2, 3, 4, 5, 6].map(function (n) { return \'<option\' + (n === S.pers ? \' selected\' : \'\') + \'>\' + n + \'<\\/option>\'; }).join(\'\');\\n    return \'<p class=\\\"nt\\\">\' + etiqueta(S.fecha) + \' \\u00b7 \' + S.hora + \'<\\/p>\' +\\n      \'<div class=\\\"pl\\\"><small>2.\\u00ba PISO \\u00b7 P\\u00daBLICO GENERAL<\\/small><div class=\\\"mz\\\">\' + [1,2,3,4,5,6,7,8].map(mesaBtn).join(\'\') + \'<\\/div><\\/div>\' +\\n      \'<div class=\\\"pl\\\"><small>1.er PISO \\u00b7 \\u267f ACCESIBLE<\\/small><div class=\\\"mz\\\">\' + [9,10,11,12].map(mesaBtn).join(\'\') + \'<\\/div><\\/div>\' +\\n      \'<p class=\\\"nt\\\">Verde: libre \\u00b7 Rojo: ocupada \\u00b7 Morado: tu mesa<\\/p>\' +\\n      \'<label for=\\\"chNm\\\">Nombre completo<\\/label><input id=\\\"chNm\\\" type=\\\"text\\\" required value=\\\"\' + esc(S.nombre) + \'\\\">\' +\\n      \'<label for=\\\"chPs\\\">Cantidad de personas<\\/label><select id=\\\"chPs\\\">\' + opts + \'<\\/select>\';\\n  }\\n\\n  function enPedido(n) { return S.pedido.some(function (x) { return x.n === n; }); }\\n  function vPedido() {\\n    var t = tot(S.pedido);\\n    return \'<p>Elige tus platos y bebidas. Es opcional.<\\/p>\' + MENU.map(function (x, i) {\\n      var on = enPedido(x.n);\\n      return \'<div class=\\\"ln\\\"><span>\' + x.n + \' \\u00b7 S\\/ \' + x.p + \'<\\/span>\' +\\n        \'<button class=\\\"b\' + (on ? \' m\' : \'\') + \'\\\" style=\\\"padding:4px 14px\\\" data-add=\\\"\' + i + \'\\\">\' + (on ? \'\\u2713 Quitar\' : \'\\uff0b\') + \'<\\/button><\\/div>\';\\n    }).join(\'\') +\\n      \'<div class=\\\"ln\\\"><b>Total<\\/b><b>S\\/ \' + (t || GARANTIA) + \'<\\/b><\\/div>\' +\\n      (t ? \'\' : \'<p class=\\\"nt\\\">Sin platos se cobra una garant\\u00eda de S\\/ \' + GARANTIA + \', que se descuenta de tu cuenta.<\\/p>\');\\n  }\\n\\n  function vPago() {\\n    return \'<div class=\\\"c\\\"><p>MONTO A PAGAR<\\/p><h2 style=\\\"font-size:30px\\\">S\\/ \' + (tot(S.pedido) || GARANTIA) + \'<\\/h2><p>OPCIONES DE PAGO<\\/p>\' +\\n      \'<div class=\\\"bt\\\" style=\\\"justify-content:center\\\"><button class=\\\"b\' + (S.pago === \'y\' ? \' m\' : \'\') + \'\\\" data-pay=\\\"y\\\">YAPE<\\/button>\' +\\n      \'<button class=\\\"b\' + (S.pago === \'e\' ? \' m\' : \'\') + \'\\\" data-pay=\\\"e\\\">EFECTIVO<\\/button><\\/div>\' +\\n      \'<p class=\\\"nt\\\">Yape \\u2192 PAGADO. Efectivo \\u2192 DEUDA (pagas en el local).<\\/p><\\/div>\';\\n  }\\n\\n  function vComp(r) {\\n    var t = tot(r.pl) || GARANTIA;\\n    return \'<div class=\\\"c l\\\"><div style=\\\"text-align:center\\\"><span class=\\\"st \' + r.e + \'\\\">\' + (r.e === \'p\' ? \'PAGADO\' : \'DEUDA\') + \'<\\/span><\\/div>\' +\\n      \'<h3 style=\\\"margin-top:12px\\\">PLATOS<\\/h3>\' +\\n      (r.pl.length ? r.pl.map(function (x) { return \'<div class=\\\"ln\\\"><span>\' + esc(x.n) + \'<\\/span><span>S\\/ \' + x.p + \'<\\/span><\\/div>\'; }).join(\'\')\\n        : \'<div class=\\\"ln\\\"><span>Garant\\u00eda de reserva<\\/span><span>S\\/ \' + GARANTIA + \'<\\/span><\\/div>\') +\\n      \'<div class=\\\"ln\\\"><b>Total<\\/b><b>S\\/ \' + t + \'<\\/b><\\/div>\' +\\n      \'<h3 style=\\\"margin-top:10px\\\">DATOS<\\/h3>\' +\\n      \'<div class=\\\"ln\\\"><span>Nombre cliente<\\/span><span>\' + esc(r.n) + \'<\\/span><\\/div>\' +\\n      \'<div class=\\\"ln\\\"><span>N.\\u00ba mesa<\\/span><span>\' + r.m + \'<\\/span><\\/div>\' +\\n      \'<div class=\\\"ln\\\"><span>Cant. personas<\\/span><span>\' + r.p + \'<\\/span><\\/div>\' +\\n      \'<div class=\\\"ln\\\"><span>Fecha<\\/span><span>\' + esc(r.f) + \'<\\/span><\\/div>\' +\\n      \'<div class=\\\"ln\\\"><span>C\\u00f3digo<\\/span><b>\' + r.c + \'<\\/b><\\/div>\' +\\n      (r.e === \'d\' ? \'<p class=\\\"er\\\">Debes pagar S\\/ \' + t + \' en el local.<\\/p>\' : \'\') +\\n      \'<p class=\\\"nt\\\">Guarda tu c\\u00f3digo para ver este comprobante en \\u00abMi reserva\\u00bb. Constancia de reserva y pago; no es boleta electr\\u00f3nica.<\\/p>\' +\\n      \'<div class=\\\"bt\\\"><button class=\\\"b\\\" data-pr>DESCARGAR PDF<\\/button><button class=\\\"b m\\\" data-fin>FINALIZAR \\u2192<\\/button><\\/div><\\/div>\';\\n  }\\n\\n  \\/* ===== Dibujar ===== *\\/\\n  function draw(scroll) {\\n    var p = S.paso, h = pasos();\\n    if (p === 1) h += vFecha();\\n    if (p === 2) h += vMesa();\\n    if (p === 3) h += vPedido();\\n    if (p === 4) h += vPago();\\n    if (p === 5) h += vComp(S.last);\\n    else {\\n      h += \'<div class=\\\"er\\\" id=\\\"chEr\\\"><\\/div><div class=\\\"bt\\\">\' +\\n        (p > 1 ? \'<button class=\\\"b\\\" data-st=\\\"-1\\\">\\u2190 ATR\\u00c1S<\\/button>\' : \'\') +\\n        \'<button class=\\\"b m\\\" data-st=\\\"1\\\">\' + (p === 4 ? \'CONFIRMAR PAGO\' : \'CONTINUAR \\u2192\') + \'<\\/button><\\/div>\';\\n    }\\n    root.innerHTML = h;\\n    if (scroll) root.scrollIntoView({ behavior: \'smooth\', block: \'start\' });\\n  }\\n  function err(m) { var e = root.querySelector(\'#chEr\'); if (e) e.textContent = m; }\\n\\n  \\/* ===== Confirmar y guardar ===== *\\/\\n  function confirmar() {\\n    var db = ld(KEY_DB) || [], c;\\n    do { c = \'CHI-\' + (1000 + Math.floor(Math.random() * 9000)); } while (db.some(function (r) { return r.c === c; }));\\n    var r = {\\n      c: c, n: S.nombre.trim(), m: S.mesa, p: S.pers,\\n      f: etiqueta(S.fecha) + \' \\u00b7 \' + S.hora, iso: S.fecha, h: S.hora,\\n      e: S.pago === \'y\' ? \'p\' : \'d\', pl: S.pedido.slice()\\n    };\\n    db.push(r); sv(KEY_DB, db); sv(KEY_PED, [], true);\\n    S.last = r; S.pedido = []; S.pago = null; S.paso = 5;\\n    draw(true);\\n  }\\n\\n  \\/* ===== Eventos ===== *\\/\\n  root.addEventListener(\'input\', function (e) {\\n    if (e.target.id === \'chNm\') S.nombre = e.target.value;\\n    if (e.target.id === \'chPs\') S.pers = +e.target.value;\\n  });\\n  root.addEventListener(\'click\', function (e) {\\n    var t = e.target, x;\\n    if ((x = t.closest(\'[data-nav]\')) && !x.disabled) { S.m += +x.dataset.nav; if (S.m > 11) { S.m = 0; S.y++; } if (S.m < 0) { S.m = 11; S.y--; } draw(); return; }\\n    if ((x = t.closest(\'[data-d]\'))) { S.fecha = x.dataset.d; S.hora = null; S.mesa = null; draw(); return; }\\n    if ((x = t.closest(\'[data-h]\'))) { S.hora = x.dataset.h; S.mesa = null; draw(); return; }\\n    if ((x = t.closest(\'[data-m]\'))) { S.mesa = +x.dataset.m; draw(); return; }\\n    if ((x = t.closest(\'[data-add]\'))) {\\n      var it = MENU[+x.dataset.add];\\n      if (enPedido(it.n)) S.pedido = S.pedido.filter(function (z) { return z.n !== it.n; });\\n      else S.pedido.push({ n: it.n, p: it.p });\\n      sv(KEY_PED, S.pedido, true); draw(); return;\\n    }\\n    if ((x = t.closest(\'[data-pay]\'))) { S.pago = x.dataset.pay; draw(); return; }\\n    if (t.closest(\'[data-pr]\')) { window.print(); return; }\\n    if (t.closest(\'[data-fin]\')) { window.location.href = GRACIAS; return; }\\n    if ((x = t.closest(\'[data-st]\'))) {\\n      var d = +x.dataset.st;\\n      if (d > 0) {\\n        if (S.paso === 1 && !(S.fecha && S.hora)) return err(\'Elige un d\\u00eda y una hora.\');\\n        if (S.paso === 2) {\\n          if (!S.mesa) return err(\'Elige una mesa libre (verde).\');\\n          if (!S.nombre.trim()) return err(\'Escribe tu nombre.\');\\n        }\\n        if (S.paso === 4) {\\n          if (!S.pago) return err(\'Elige Yape o efectivo.\');\\n          return confirmar();\\n        }\\n      }\\n      S.paso += d; draw(true);\\n    }\\n  });\\n\\n  draw();\\n})();\\n<\\/script>\\n\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false}]'),
